   809  static inline void
   810  hb_propagate_flags (hb_buffer_t *buffer)
   811  {
   812    /* Propagate cluster-level glyph flags to be the same on all cluster glyphs.
   813     * Simplifies using them. */
   814
   815    if (!(buffer->scratch_flags & HB_BUFFER_SCRATCH_FLAG_HAS_UNSAFE_TO_BREAK))
   816      return;
   817
   818    hb_glyph_info_t *info = buffer->info;
   819
   820    foreach_cluster (buffer, start, end)
   821    {
   822      unsigned int mask = 0;
   823      for (unsigned int i = start; i < end; i++)
   824        if (info[i].mask & HB_GLYPH_FLAG_UNSAFE_TO_BREAK)
   825        {
   826           mask = HB_GLYPH_FLAG_UNSAFE_TO_BREAK;
   827           break;
   828        }
   829      if (mask)
   830        for (unsigned int i = start; i < end; i++)
   831          info[i].mask |= mask;
   832    }
   833  }
