   358                                  const void *match_data_,
   359                                  const HBUINT16 glyph_data[])
   360      {
   361        matcher.set_match_func (match_func_, match_data_);
   362        match_glyph_data = glyph_data;
   363      }
   364
   365      inline void reset (unsigned int start_index_,
   366                         unsigned int num_items_)
   367      {
   368        idx = start_index_;
   369        num_items = num_items_;
   370        end = c->buffer->len;
   371        matcher.set_syllable (start_index_ == c->buffer->idx ? c->buffer->cur().syllable () : 0);
   372      }
   373
   374      inline void reject (void) { num_items++; match_glyph_data--; }
   375
   376      inline matcher_t::may_skip_t
   377      may_skip (const hb_glyph_info_t    &info) const
   378      {
   379        return matcher.may_skip (c, info);
   380      }
   381
   382      inline bool next (void)
   383      {
   384        assert (num_items > 0);
   385        while (idx + num_items < end)
   386        {
   387          idx++;
   388          const hb_glyph_info_t &info = c->buffer->info[idx];
   389
   390          matcher_t::may_skip_t skip = matcher.may_skip (c, info);
   391          if (unlikely (skip == matcher_t::SKIP_YES))
   392            continue;
   393
   394          matcher_t::may_match_t match = matcher.may_match (info, match_glyph_data);
   395          if (match == matcher_t::MATCH_YES ||
   396              (match == matcher_t::MATCH_MAYBE &&
   397               skip == matcher_t::SKIP_NO))
   398          {
   399            num_items--;
   400            match_glyph_data++;
   401            return true;
   402          }
   403
   404          if (skip == matcher_t::SKIP_NO)
   405            return false;
   406        }
   407        return false;
   408      }
   409      inline bool prev (void)
   410      {
   411        assert (num_items > 0);
   412        while (idx > num_items - 1)
   413        {
   414          idx--;
   415          const hb_glyph_info_t &info = c->buffer->out_info[idx];
   416
   417          matcher_t::may_skip_t skip = matcher.may_skip (c, info);
   418          if (unlikely (skip == matcher_t::SKIP_YES))
   419            continue;
   420
   421          matcher_t::may_match_t match = matcher.may_match (info, match_glyph_data);
   422          if (match == matcher_t::MATCH_YES ||
   423              (match == matcher_t::MATCH_MAYBE &&
   424               skip == matcher_t::SKIP_NO))
   425          {
   426            num_items--;
